// LoadUser loads the alertHistory's User into the .R struct
func (o *AlertHistory) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.User = nil

	related, err := o.User(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AlertHistories = AlertHistorySlice{o}

	o.R.User = related
	return nil
}

// LoadUser loads the alertHistory's User into the .R struct
func (os AlertHistorySlice) LoadUser(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	users, err := os.User(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range users {

			if !(o.UserID == rel.ID) {
				continue
			}

			rel.R.AlertHistories = append(rel.R.AlertHistories, o)

			o.R.User = rel
			break
		}
	}

	return nil
}

// LoadAlertRule loads the alertHistory's AlertRule into the .R struct
func (o *AlertHistory) LoadAlertRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AlertRule = nil

	related, err := o.AlertRule(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.AlertHistories = AlertHistorySlice{o}

	o.R.AlertRule = related
	return nil
}

// LoadAlertRule loads the alertHistory's AlertRule into the .R struct
func (os AlertHistorySlice) LoadAlertRule(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	alertRules, err := os.AlertRule(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range alertRules {
			if !o.AlertRuleID.IsValue() {
				continue
			}

			if !(o.AlertRuleID.IsValue() && o.AlertRuleID.MustGet() == rel.ID) {
				continue
			}

			rel.R.AlertHistories = append(rel.R.AlertHistories, o)

			o.R.AlertRule = rel
			break
		}
	}

	return nil
}

type alertHistoryJoins[Q dialect.Joinable] struct {
	typ       string
	User      modAs[Q, userColumns]
	AlertRule modAs[Q, alertRuleColumns]
}

func (j alertHistoryJoins[Q]) aliasedAs(alias string) alertHistoryJoins[Q] {
	return buildAlertHistoryJoins[Q](buildAlertHistoryColumns(alias), j.typ)
}

func buildAlertHistoryJoins[Q dialect.Joinable](cols alertHistoryColumns, typ string) alertHistoryJoins[Q] {
	return alertHistoryJoins[Q]{
		typ: typ,
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.Name().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
		AlertRule: modAs[Q, alertRuleColumns]{
			c: AlertRules.Columns,
			f: func(to alertRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertRules.Name().As(to.Alias())).On(
						to.ID.EQ(cols.AlertRuleID),
					))
				}

				return mods
			},
		},
	}
}
